const upsertSessionFactor = `-- name: UpsertSessionFactor :one

INSERT INTO mod_users.session_factors (session_id, credential_id, asserted_acr)
VALUES ($1, $2, $3)
ON CONFLICT (session_id, credential_id) DO UPDATE
SET verified_at = now(),
    asserted_acr = EXCLUDED.asserted_acr
RETURNING session_id, credential_id, asserted_acr, verified_at
`

type UpsertSessionFactorParams struct {
	SessionID    int64       `json:"session_id"`
	CredentialID int64       `json:"credential_id"`
	AssertedAcr  pgtype.Int2 `json:"asserted_acr"`
}

// ---------------------------------------------------------------------------
// Session factors
// ---------------------------------------------------------------------------
// Add a factor, or re-verify it (step-up). MF101 when the credential belongs to
// another principal.
func (q *Queries) UpsertSessionFactor(ctx context.Context, arg UpsertSessionFactorParams) (SessionFactor, error) {
	row := q.db.QueryRow(ctx, upsertSessionFactor, arg.SessionID, arg.CredentialID, arg.AssertedAcr)
	var i SessionFactor
	err := row.Scan(
		&i.SessionID,
		&i.CredentialID,
		&i.AssertedAcr,
		&i.VerifiedAt,
	)
	return i, err
}

const useRefreshToken = `-- name: UseRefreshToken :one
UPDATE mod_users.session_refresh_tokens
SET used_at = now()
WHERE token_hash = $1
  AND used_at IS NULL
  AND expires_at > now()
RETURNING id, session_id, replaced_by_id, lineage_uuid, token_hash, used_at, created_at, expires_at
`

// Atomic rotation step: marks a live, unused token used. No row means the
// token is already used (reuse), expired, or unknown; the caller then looks it
// up with GetRefreshTokenByHash to tell the cases apart.
func (q *Queries) UseRefreshToken(ctx context.Context, tokenHash string) (SessionRefreshToken, error) {
	row := q.db.QueryRow(ctx, useRefreshToken, tokenHash)
	var i SessionRefreshToken
	err := row.Scan(
		&i.ID,
		&i.SessionID,
		&i.ReplacedByID,
		&i.LineageUuid,
		&i.TokenHash,
		&i.UsedAt,
		&i.CreatedAt,
		&i.ExpiresAt,
	)
	return i, err
}
